            ["Manuel olarak seç"] = "Pick manually",
            ["winget'te olmayan {0} program"] = "{0} apps not on winget",
            ["Hepsi winget ile kurulabiliyor."] = "All of them can be installed with winget.",
            ["Bunlar elle kurulmalı; listeyi masaüstüne kaydedip sonra tek tek indirebilirsin."] = "These need to be installed manually; save the list to your desktop and download them one by one later.",
            ["Elle kurulacak programlar - {0}"] = "Apps to install manually - {0}",
            ["Kahya · winget ile kurulamayan programlar ({0} bilgisayarından, {1:dd.MM.yyyy})"] = "Kahya · apps that can't be installed with winget (from {0}, {1:dd.MM.yyyy})",
            ["Bunları üreticinin sitesinden indirip kurman gerekiyor. İnternette \"<ad> indir\" diye aratabilirsin."] = "Download these from the maker's website. You can search the web for \"<name> download\".",
            ["Kaydedildi ✓"] = "Saved ✓",
            ["Listeyi masaüstüne kaydet"] = "Save list to desktop",
            ["Kurulacak programları seç; hepsinin en yeni sürümü winget ile kurulur. Kurulum ilk sırada yapılır, ayarlar ve oyun kayıtları onlardan sonra gelir."] = "Pick the apps to install; the latest version of each is installed with winget. Apps are installed first; settings and game saves come after them.",
            ["Her kategoriyi açıp içindekileri tek tek seçebilirsin. Programlardan sonra yüklenir; oyun kayıtları en sonda. Var olan dosyaların daha yenisi varsa üzerine yazılmaz."] = "Open each category to pick items one by one. Restored after the apps; game saves last. Newer existing files are not overwritten.",
