            ["Geri yükleme durduruldu."] = "Restore stopped.",
            ["Asistanı yeniden açınca kaldığı yerden devam eder."] = "Reopen the assistant to continue where it left off.",
            ["Önce geri yüklenecek en az bir şey seç."] = "Pick at least one thing to restore first.",
            ["Durduruluyor…"] = "Stopping…",
            ["Geri yükleme sürüyor. Durdurup kapatılsın mı? Sonra kaldığı yerden devam edebilirsin."] = "A restore is in progress. Stop and close? You can continue where you left off later.",
            ["{0} (önceden yapılmıştı)"] = "{0} (already done)",
